-- Daily challenges for 2026-09-28: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-09-28

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('making-room-for-play', 'Making Room for Play', 'For grown-ups whose days are all obligations and no fun. Each day is one small invitation to play, make, or mess around for its own sake, so lightness gets a regular place in the week.', 'Play', 365, array['Self-Care', 'Stress']::text[], 1, '2026-09-28T17:00:00+00:00'::timestamptz),
  ('slowing-down-at-meals', 'Slowing Down at Meals', 'For anyone who eats standing up, over a screen, or without noticing. Each day is one small way to make a meal a pause, so eating becomes a moment in your day instead of something that happens to you.', 'Body', 365, array['Food', 'Mindfulness']::text[], 1, '2026-09-28T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('making-room-for-play', 'slowing-down-at-meals');

